function o(n){return n instanceof Date&&!Number.isNaN(n.getTime())}function r(n){const t=n instanceof Date?n:new Date(n);return o(t)?t:null}function a(n){const t=r(n);return t?`${String(t.getHours()).padStart(2,"0")}:${String(t.getMinutes()).padStart(2,"0")}`:""}function i(n){const t=r(n);return t?`${t.getMonth()+1}/${t.getDate()} ${a(t)}`:""}function u(n){const t=r(n);if(!t)return"";const e=new Date;return t.toDateString()===e.toDateString()?a(t):`${t.getMonth()+1}/${t.getDate()}`}function s(n,t="zh-CN"){const e=r(n);return e?e.toLocaleDateString(t):""}function c(n,t="zh-CN"){const e=r(n);return e?e.toLocaleString(t,{month:"short",day:"numeric",hour:"2-digit",minute:"2-digit"}):""}export{c as a,u as b,a as c,i as d,s as f};
